import java.io.BufferedReader;import java.io.InputStreamReader;import java.io.PrintWriter;import java.util.StringTokenizer;import java.io.IOException;public class Main {public static void main(String[] args) throws IOException {BufferedReader br = new BufferedReader(new InputStreamReader(System.in));PrintWriter out = new PrintWriter(System.out);String line = br.readLine();if (line != null) {int n = Integer.parseInt(line.trim());int[] result = new int[n];StringTokenizer st = new StringTokenizer(br.readLine());for (int i = 1; i <= n; i++) {int recipient = Integer.parseInt(st.nextToken());result[recipient - 1] = i;}for (int i = 0; i < n; i++) {out.print(result[i] + (i == n - 1 ? "" : " "));}out.println();}out.flush();out.close();}}